files..promptscript/project.prs:
@meta {
  id: "acme-support"
  syntax: "1.6.0"
  owner: "team-support"
  risk: "medium"
}

@examples {
  greeting: {
    input: "Hello"
    output: "Hi"
  }
}
@restrictions {
  - "Never share secrets"
}
@standards {
  tone: "warm"
}
@knowledge {
  """
  Refunds take five working days.
  """
}
@context {
  product: "Acme Cloud"
}
@identity {
  """
  You are the Acme support assistant.
  """
}

@prompts {
  compose: {
    description: "Answer with composed text"
    compose: [examples, restrictions, standards, knowledge, context, identity]
    system: "Answer the question."
    user: "Question: {{input.question}}"
    inputs: { question: { type: "string", description: "The question" } }
  }
}
